<script setup lang="ts">
import {computed,ref} from 'vue'
import {sharedFields,brands} from './customsData'
import CustomsChoice from './CustomsChoice.vue'
import CustomsCodePicker from './CustomsCodePicker.vue'
const props=defineProps<{modelValue:Record<string,any>,kind:'declaration'|'clearance',mode?:'shared'|'specific'|'all'}>(),picker=ref(false)
const prefix=computed(()=>props.kind==='declaration'?'报关':'清关')
const textFields=computed(()=>({...((props.mode||'all')!=='specific'?sharedFields:{}),...(props.mode!=='shared'?{name_cn:'中文'+prefix.value+'名',name_en:'英文'+prefix.value+'名',brand_type:'品牌类型',...(props.kind==='declaration'?{export_preference:'出口享惠情况',exemption:'征免',other_elements:'其他申报要素'}:{clearance_url_uk:'英国清关url',clearance_url_de:'德国清关url'})}:{})}))
const choices=['name_cn','name_en','material_cn','material_en','usage_cn','usage_en']
function choose(row:any){props.modelValue.hs_code=row.hs_code;props.modelValue.tax_rate=Number(row.tax_rate)}
</script>
<template><div class="customs-fields"><el-form-item v-for="(label,key) in textFields" :key="key" :label="String(label)"><CustomsChoice v-if="choices.includes(key)" v-model="modelValue[key]" :field="key" :label="String(label)"/><el-select v-else-if="key==='brand_type'" v-model="modelValue[key]" aria-label="品牌类型"><el-option v-for="v in brands" :value="v" :label="v"/></el-select><el-input v-else v-model="modelValue[key]" :aria-label="label" :type="key==='other_elements'?'textarea':'text'" :maxlength="key==='other_elements'||String(key).startsWith('clearance_url_')?2000:500"/></el-form-item><template v-if="mode!=='shared'"><el-form-item :label="prefix+' HSCODE'"><div class="customs-code"><el-input v-model="modelValue.hs_code" :aria-label="prefix+' HSCODE'" maxlength="30"/><el-button @click="picker=true">选择</el-button></div></el-form-item><el-form-item :label="prefix+'税率（%）'"><el-input-number v-model="modelValue.tax_rate" :min="0" :max="100" :precision="4" :controls="false" :aria-label="prefix+'税率'"/></el-form-item><el-form-item :label="prefix+'单价'"><div class="customs-price"><el-input-number v-model="modelValue.unit_price" :min="0" :precision="4" :controls="false"/><el-select v-model="modelValue.currency" placeholder="币种"><el-option value="CNY" label="人民币 CNY"/><el-option value="EUR" label="欧元 EUR"/><el-option value="GBP" label="英镑 GBP"/></el-select></div></el-form-item></template></div><CustomsCodePicker v-model="picker" :kind="kind" @select="choose"/></template>
<style scoped>.customs-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 20px}.customs-fields :deep(.el-input-number),.customs-fields .el-select{width:100%}.customs-price,.customs-code{display:flex;width:100%;gap:8px}.customs-price .el-select{flex:0 0 120px}@media(max-width:1050px){.customs-fields{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.customs-fields{grid-template-columns:1fr}}</style>
